pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address actor, uint256 id, uint256 amt) public {
        vm.assume(actor != address(0));
        id = bound(id, 0, 10);
        amt = bound(amt, 0, 1e18);

        uint256 existing = c.uniqueTokensOutstanding();
        if (existing <= id) {
            for (uint256 i = existing; i <= id; i++) {
                c.createGameItem("n", "u", false, true, 0, 0, 1);
            }
        }

        bool ok;
        try c.balanceOf(actor, id) returns (uint256 bal) {
            ok = true;
            assertTrue(bal == 0);
        } catch {
            ok = false;
            assertTrue(ok == true);
        }
    }
}
